def dispatch(ctx: Ctx, line: str) -> Outcome:
    raw = line.strip()
    if not raw:
        return Outcome()
    if raw.startswith("/"):
        return _slash(ctx, raw[1:])
    try:
        parts = shlex.split(raw)
    except ValueError as exc:
        return Outcome(error=str(exc))
    verb = parts[0].lower()
    args = parts[1:]
    handlers = {
        "ls": _ls,
        "cd": _cd,
        "pwd": _pwd,
        "tree": _tree,
        "show": _show,
        "cat": _show,
        "find": _find,
        "help": lambda c, a: Outcome(renderable=render.help_text()),
        "mpls": _mpls,
        "alarm": _alarm,
        "alarms": _alarm,
        "ne": _ne,
        "customer": _customer,
        "customers": _customer,
        "service": _service,
        "services": _service,
        "stats": _stats,
        "resync": _resync,
        "topology": lambda c, a: Outcome(renderable=render.topology_ascii()),
        "clear": lambda c, a: Outcome(clear=True),
        "quit": lambda c, a: Outcome(quit=True),
        "exit": lambda c, a: Outcome(quit=True),
        "whoami": _whoami,
        "status": _status,
        "passwd": _passwd,
        "users": _users,
        "tasks": _tasks,
    }
