{
  "find": {
    "fullClassName": "vprn.Site",
    "filter": {
      "and": {
        "wildcard": {
          "name": "objectFullName",
          "value": "svc-mgr:service-1:%"
        },
        "equal": {
          "name": "siteId",
          "value": "10.251.121.250"
        }
      }
    },
    "resultFilter": {
      "children": "",
      "attribute": [
        "objectFullName",
        "siteId",
        "serviceId",
        "administrativeState",
        "operationalState"
      ]
    }
  }
}

Resultado real:
  svc-mgr:service-1:10.251.121.250
  serviceId=10  admin=serviceUp  oper=serviceUp


